        }
    }

    for (int i = 25325981 + 1; i <= 25326023; i++) {
    }


            final int n0 = Integer.MIN_VALUE;
    final String expected0 = MessageFormat.format(Primes.NUMBER_TOO_SMALL, Integer.MIN_VALUE, 0);
